// packages/api/dist/application/shop.service.js
async function list(filters) {
  const where = { user: { deletedAt: null, id: { notIn: await searchBlockedUserIds() } } };
  if (filters.city)
    where.city = { contains: filters.city, mode: "insensitive" };
  if (filters.verified !== void 0) {
    where.verificationStatus = filters.verified ? "verified" : "pending";
  }
  if (filters.specialty) {
    where.specialties = { path: [], array_contains: filters.specialty };
  }
  const [total, shops] = await Promise.all([
    prisma.shop.count({ where }),
    prisma.shop.findMany({
      where,
      skip: (filters.page - 1) * filters.limit,
      take: filters.limit,
      orderBy: { ratingAvg: "desc" },
      select: {
        id: true,
        name: true,
        address: true,
        city: true,
        specialties: true,
        verificationStatus: true,
        ratingAvg: true
      }
    })
  ]);
  return { data: shops, meta: { page: filters.page, limit: filters.limit, total } };
}
async function findById(id3) {
  return prisma.shop.findUnique({
    where: { id: id3 },
    select: {
      id: true,
      name: true,
      address: true,
      city: true,
      lat: true,
      lng: true,
      specialties: true,
      verificationStatus: true,
      ratingAvg: true
    }
  });
}
async function getAvailability(shopId, date2) {
  const where = { shopId };
  if (date2) {
    const start = new Date(date2);
    const end = new Date(date2);
    end.setDate(end.getDate() + 1);
    where.scheduledAt = { gte: start, lt: end };
  }
  const appointments = await prisma.appointment.findMany({
    where,
    select: { scheduledAt: true, status: true },
    orderBy: { scheduledAt: "asc" }
  });
  return appointments;
}

