// packages/api/dist/application/appointments/policy.js
function canTransitionAppointment(role, from, to) {
  if (role === "dueno")
    return to === "cancelled" && (from === "pending" || from === "confirmed");
  if (role === "taller") {
    if (from === "pending")
      return to === "confirmed" || to === "cancelled";
    if (from === "confirmed")
      return to === "completed" || to === "cancelled";
  }
  return false;
}

