    const appointment = await tx.appointment.create({
      data: { vehicleId: input.vehicleId, shopId: input.shopId, ownerId, scheduledAt, summary: input.summary },
      include: { vehicle: { select: { id: true, make: true, model: true } }, shop: { select: { id: true, name: true } } }
    });
    await tx.auditLog.create({ data: { eventType: "appointment.requested", actorUserId: ownerId, actorRole: "dueno", entityType: "Appointment", entityId: appointment.id, after: { status: "pending", scheduledAt: scheduledAt.toISOString() } } });
