var PART_MONEY_SCRIPT = `
const PART_RETURN_TEXT={solicitada:'pedida, espera al almac\xE9n',aceptada:'aceptada',rechazada:'rechazada'};
const PART_METHODS=[['efectivo','Efectivo'],['transferencia','Transferencia'],['tarjeta','Tarjeta'],['otra','Otra']];
function partChargeBtn(p){const b=btn('Registrar cobro','ghost',()=>{const f=h('form',{class:'acts'});const amount=h('input',{type:'number',required:true,min:'0',step:'any',inputmode:'decimal','aria-label':'Valor cobrado en USD',placeholder:'Valor USD'});const how=h('select',{'aria-label':'Forma de pago'},...PART_METHODS.map(m=>h('option',{value:m[0],text:m[1]})));const ref=h('input',{maxlength:'120','aria-label':'Referencia',placeholder:'Referencia (opcional)'});f.append(amount,how,ref,h('button',{class:'ghost'},'Enviar'));f.onsubmit=e=>{e.preventDefault();void act(['Cobro '+p.ref,amount.value.trim(),how.value,...(ref.value.trim()?[ref.value.trim()]:[])],{btn:sub(e),ask:'\xBFRegistrar este cobro? Quien compr\xF3 deber\xE1 confirmarlo. AutoMantPro no mueve dinero.'});};b.replaceWith(f);amount.focus();});return b;}
function partMoneyActs(p){const acts=h('div',{class:'chips'});
 if(p.can.charge)acts.append(partChargeBtn(p));
 if(p.can.answerPayment){const q=p.payment.pending;acts.append(abtn('Confirmar pago de '+usd(q.amountUsd),'primary',['Confirmo pago '+p.ref],'\xBFConfirmar que pagaste '+usd(q.amountUsd)+' por '+q.method+'?'),reasonBtn('Observar pago',(why,b)=>act(['Observo pago '+p.ref,why],{btn:b,ask:'\xBFEnviar tu observaci\xF3n sobre este cobro?'})));}
 if(p.can.requestReturn)acts.append(reasonBtn('Devolver repuesto',(why,b)=>act(['Devolver '+p.ref,why],{btn:b,ask:'\xBFPedir al almac\xE9n que acepte la devoluci\xF3n? AutoMantPro no mueve dinero ni revierte cobros.'})));
 if(p.can.answerReturn)acts.append(abtn('Aceptar devoluci\xF3n','primary',['Aceptar devoluci\xF3n '+p.ref],'\xBFAceptar la devoluci\xF3n? Se le avisar\xE1 a quien compr\xF3.'),reasonBtn('Rechazar devoluci\xF3n',(why,b)=>act(['Rechazar devoluci\xF3n '+p.ref,why],{btn:b,ask:'\xBFRechazar la devoluci\xF3n? Se le avisar\xE1 a quien compr\xF3 con tu motivo.'})));
 return acts;}
function partMoneyCard(d){const list=h('div',{class:'list'});
 for(const p of d.partMoney){const pay=p.payment;const wait=p.can.answerPayment||p.can.answerReturn||p.can.charge;
  const info=[h('b',{text:p.category+' \xB7 '+p.ref}),h('small',{text:p.description}),h('small',{text:(p.storeName?p.storeName+' \xB7 ':'Para ')+p.vehicle+(p.priceUsd!==null?' \xB7 '+usd(p.priceUsd):'')+' \xB7 '+(p.state==='entregado'?'entregado':'por entregar')})];
  if(p.orderText)info.push(h('small',{text:p.orderText}));
  if(pay.paidUsd||pay.informedUsd)info.push(h('small',{text:'Pagado '+usd(pay.paidUsd)+(pay.informedUsd?' \xB7 por confirmar '+usd(pay.informedUsd):'')+' \xB7 saldo '+usd(pay.balanceUsd)}));
  if(pay.observed&&!pay.pending)info.push(h('small',{text:'Cobro observado: '+pay.observed}));
  if(p.returned)info.push(h('small',{text:'Devoluci\xF3n '+PART_RETURN_TEXT[p.returned.status]+': '+p.returned.reason+(p.returned.storeNote?' \xB7 Almac\xE9n: '+p.returned.storeNote:'')}));
  list.append(h('div',{class:'line st-'+(wait?'pronto':'al_dia')},h('div',{},...info)),partMoneyActs(p));}
 return card('Cobro y devoluci\xF3n de repuestos',d.partMoney.length+(d.partMoney.length===1?' pedido':' pedidos'),list,h('p',{class:'note',text:'AutoMantPro solo registra los cobros y las devoluciones; no mueve dinero.'}));}
`;

// packages/api/dist/interfaces/comprobante-panel-script.js
var COMPROBANTE_SCRIPT = `
let ordersMine=false;
function photoAlt(kind){return kind==='ingreso'?'Foto del ingreso':kind==='avance'?'Foto del avance del trabajo':'Comprobante de pago';}
// Las p\xE1ginas imprimibles se abren con un enlace firmado de 10 minutos que pide el servidor.
async function openPrint(path,b){b.disabled=true;const w=window.open('about:blank','_blank');if(w)w.opener=null;try{const r=await api(path,{method:'POST',body:'{}'});if(w)w.location.href=r.url;else showResult('Abre este enlace para ver el documento: '+location.origin+r.url);}catch(err){if(w)w.close();showResult(err.message);}finally{b.disabled=false;}}
function receiptBtn(o){return btn('Comprobante','ghost',ev=>void openPrint('/pilot/orders/'+o.code+'/comprobante-link',ev.currentTarget));}
function ownerOrderExtras(o){const out=[receiptBtn(o)];if(o.canDecide!==false&&!(o.records&&o.records.intake))out.push(photosBox(o.code));return out;}
function progressPhotoForm(o){const b=btn('Subir fotos de avance','ghost',()=>{const f=h('form',{class:'acts'});const photos=photoInput('Fotos del avance (hasta 6 por orden)');const send=h('button',{class:'primary'},'Subir fotos');f.append(photos,send);f.onsubmit=async e=>{e.preventDefault();const files=photos.querySelector('input').files;if(!files.length){showResult('Elige al menos una foto.');return;}send.disabled=true;const failed=await uploadPhotos(o.code,'avance',files);send.disabled=false;showResult(failed?'No pudimos subir '+failed+' foto(s). Deben ser JPG o PNG, y cada orden admite hasta 6 fotos de avance.':'Listo: subimos las fotos. El due\xF1o las ve con \xABVer fotos\xBB.');if(!failed)loadPanel(generation,panelVehicle).catch(()=>{});};b.replaceWith(f);});return b;}
function assignTechForm(o,d){const b=btn('Asignar t\xE9cnico','ghost',()=>{const f=h('form',{class:'acts'});const sel=h('select',{'aria-label':'T\xE9cnico de la orden'},h('option',{value:'',text:'Sin t\xE9cnico'}),...d.team.technicians.map(t=>h('option',{value:t.id,text:t.name})));const send=h('button',{class:'ghost'},'Guardar');f.append(sel,send);f.onsubmit=async e=>{e.preventDefault();send.disabled=true;try{const res=await api('/pilot/orders/'+o.code+'/technician',{method:'POST',body:JSON.stringify({memberId:sel.value||null})});showResult(res.message);loadPanel(generation,panelVehicle).catch(()=>{});}catch(err){showResult(err.message);send.disabled=false;}};b.replaceWith(f);});return b;}
function shopOrderExtras(o,d){const out=[receiptBtn(o)];const open=o.status!=='cerrada'&&o.status!=='cancelada';if(open)out.push(progressPhotoForm(o));if(!(o.records&&o.records.intake))out.push(photosBox(o.code));if(open&&d.canManage&&d.team&&d.team.technicians.length)out.push(assignTechForm(o,d));return out;}
function assignmentNote(o,d){const a=d.team&&d.team.assignments[o.code];if(!a)return h('span');return a.mine?h('p',{class:'note'},h('span',{class:'tag st-al_dia',text:'Tuya'}),' T\xE9cnico asignado: t\xFA'):h('p',{class:'note',text:'T\xE9cnico asignado: '+a.name});}
function ordersView(d){if(!ordersMine||!d.team)return d;return Object.assign({},d,{orders:d.orders.filter(o=>d.team.assignments[o.code]&&d.team.assignments[o.code].mine)});}
function ordersFilterBar(d){if(!d.team||!d.team.me.isTechnician)return null;const pick=v=>()=>{ordersMine=v;renderPanel();};return h('div',{class:'chips'},btn('Todas las \xF3rdenes',ordersMine?'ghost':'primary',pick(false)),btn('Mis \xF3rdenes',ordersMine?'primary':'ghost',pick(true)));}
function productivityCard(d){const p=d.team&&d.team.productivity;if(!p)return null;const list=h('div',{class:'list'});if(!p.rows.length)list.append(h('p',{class:'note',text:'Todav\xEDa no hay t\xE9cnicos con actividad esta semana.'}));for(const r of p.rows)list.append(h('div',{class:'row2'},h('b',{text:r.name}),h('span',{class:'pill',text:r.orders+(r.orders===1?' orden':' \xF3rdenes')+' \xB7 '+r.closed+(r.closed===1?' cerrada':' cerradas')+' \xB7 '+r.services+(r.services===1?' servicio':' servicios')})));return card('Productividad de la semana','desde el '+ecDate(p.since,{day:'numeric',month:'short'}),list,h('p',{class:'note',text:'\xD3rdenes asignadas o cerradas en la semana y servicios que cada persona registr\xF3 en el taller.'}),abtn('Ver resumen de la semana','ghost',['Resumen semana']));}
function vehicleToolsBox(v){const box=h('div',{class:'stack'});box.append(h('div',{class:'chips'},btn('Historial del veh\xEDculo','ghost',ev=>void openPrint('/pilot/vehicles/'+v.id+'/history-link',ev.currentTarget)),btn('Cambiar de propietario','ghost',async ev=>{const b=ev.currentTarget;if(!window.confirm('\xBFGenerar un c\xF3digo para pasar este veh\xEDculo a otra persona? Cuando lo use, el veh\xEDculo y su historial pasan a su cuenta y t\xFA pierdes el acceso. Tus gastos no se comparten.'))return;b.disabled=true;try{const r=await api('/pilot/vehicles/'+v.id+'/transfer',{method:'POST',body:'{}'});showResult('C\xF3digo para entregar '+r.vehicleLabel+': '+r.code+'. Se usa una sola vez y vale hasta el '+ecDate(r.expiresAt,{day:'numeric',month:'long',year:'numeric'})+'. Si generas otro, este deja de servir. Quien lo reciba debe tener cuenta en AutoMantPro.');}catch(err){showResult(err.message);}finally{b.disabled=false;}})));return box;}
function receiveVehicleBox(){const f=h('form',{class:'acts'});const code=h('input',{required:true,maxlength:'20','aria-label':'C\xF3digo del veh\xEDculo',placeholder:'C\xF3digo V-XXXXXXXX',autocomplete:'off'});const send=h('button',{class:'ghost'},'Recibir veh\xEDculo');f.append(code,send);f.onsubmit=async e=>{e.preventDefault();if(!window.confirm('\xBFRecibir este veh\xEDculo? Pasa a tu cuenta con su historial de servicios.'))return;send.disabled=true;try{const r=await api('/pilot/vehicle-transfer/redeem',{method:'POST',body:JSON.stringify({code:code.value.trim()})});showResult('Listo: recibiste '+r.vehicleLabel+' con '+r.services+(r.services===1?' servicio':' servicios')+' en su historial.');code.value='';loadPanel(generation,r.vehicleId).catch(()=>{});}catch(err){showResult(err.message);}finally{send.disabled=false;}};return h('details',{},h('summary',{text:'Recibir un veh\xEDculo con c\xF3digo'}),f);}
`;

