var CATALOG_SCRIPT = `
const TARIFF_NOTE='Valor referencial; el presupuesto final lo da el taller.';
const DAY_LIST=[['lun','Lunes'],['mar','Martes'],['mie','Mi\xE9rcoles'],['jue','Jueves'],['vie','Viernes'],['sab','S\xE1bado'],['dom','Domingo']];
function numberOrNull(v){const t=String(v||'').trim();if(t==='')return null;const n=Number(t.replace(',','.'));return Number.isFinite(n)?n:NaN;}
function inp(label,attrs){const input=h('input',Object.assign({'aria-label':label,placeholder:label},attrs||{}));return input;}
function afterSave(done,box){return async work=>{try{const msg=await work();status(msg||'Listo.');await done();}catch(err){status(err.message);if(box)box.disabled=false;}};}
// ---------- Cat\xE1logo del almac\xE9n ----------
function catalogCard(){
 const list=h('div',{class:'list'});const pager=h('div',{class:'chips'});let page=1;
 const c=card('Mi cat\xE1logo',null,h('p',{class:'note',text:'Lo que cargas aqu\xED lo ven los due\xF1os cuyo veh\xEDculo coincide con la compatibilidad que indiques. No se muestran tel\xE9fonos.'}),h('p',{class:'note',text:'Cargando tu cat\xE1logo\u2026'}),list,pager);c.id='catalogo';
 const intro=c.children[2];
 const load=async p=>{page=p||page;const epoch=generation;let data;try{data=await api('/pilot/catalog?page='+page);}catch(err){intro.textContent=err.message;return;}
  if(epoch!==generation)return;list.replaceChildren();pager.replaceChildren();
  intro.textContent=data.total?data.total+(data.total===1?' producto':' productos')+' en tu cat\xE1logo.':'Todav\xEDa no tienes productos. Agrega el primero abajo.';
  if(data.updatePending)intro.textContent+=' Para desactivar productos y cargar compatibilidades, el equipo debe activar esta funci\xF3n.';
  for(const it of data.items)list.append(productRow(it,()=>load(page)));
  if(data.page>1||data.hasMore)pager.append(data.page>1?btn('Anteriores','ghost',()=>load(page-1)):null,data.hasMore?btn('Ver m\xE1s productos','ghost',()=>load(page+1)):null,h('span',{class:'note',text:'P\xE1gina '+data.page+' de '+Math.max(1,Math.ceil(data.total/data.pageSize))}));};
 c.append(productAddForm(()=>load(1)),productImportForm(()=>load(1)));void load(1);return c;}
function productImportForm(done){
 const file=h('input',{type:'file',accept:'.csv,text/csv,text/plain','aria-label':'Archivo CSV del cat\xE1logo',required:true});
 const send=h('button',{class:'ghost full'},'Cargar archivo');
 const f=h('form',{class:'stack'},h('p',{class:'sub',text:'Cargar varios productos con un archivo CSV'}),h('p',{class:'note',text:'Columnas en este orden: nombre, precio, stock, marca, modelo, a\xF1o desde, a\xF1o hasta. Solo nombre y precio son obligatorios. Sirve el CSV que guarda Excel. Si un producto ya existe con el mismo nombre, se actualizan su precio y su stock. Si hay un error, no se carga nada y te decimos en qu\xE9 l\xEDnea.'}),file,send);
 f.onsubmit=async e=>{e.preventDefault();const picked=file.files&&file.files[0];if(!picked){status('Elige el archivo CSV.');return;}if(picked.size>200000){status('El archivo es muy grande. Divide el cat\xE1logo en partes de hasta 500 productos.');return;}
  send.disabled=true;
  try{const csv=await picked.text();const r=await api('/pilot/catalog/import',{method:'POST',body:JSON.stringify({csv})});f.reset();status('Carga lista: '+r.created+(r.created===1?' producto nuevo, ':' productos nuevos, ')+r.updated+(r.updated===1?' actualizado y ':' actualizados y ')+r.fitments+(r.fitments===1?' compatibilidad agregada.':' compatibilidades agregadas.'));await done();}
  catch(err){status(err.message);}finally{send.disabled=false;}};
 return f;}
function productAddForm(done){
 const name=inp('Nombre del producto',{required:true,maxlength:'191'});
 const price=inp('Precio en USD',{type:'number',required:true,min:'0.01',max:'99999999',step:'0.01',inputmode:'decimal'});
 const stock=inp('Stock (opcional)',{type:'number',min:'0',max:'1000000',step:'1',inputmode:'numeric'});
 const make=inp('Marca compatible (opcional)',{maxlength:'60'});const model=inp('Modelo (opcional)',{maxlength:'60'});
 const from=inp('A\xF1o desde',{type:'number',min:'1950',max:'2100',inputmode:'numeric'});const to=inp('A\xF1o hasta',{type:'number',min:'1950',max:'2100',inputmode:'numeric'});
 const send=h('button',{class:'primary full'},'Agregar producto');
 const f=h('form',{class:'stack'},h('p',{class:'sub',text:'Agregar un producto'}),name,h('div',{class:'grid2'},price,stock),h('p',{class:'note',text:'Compatibilidad: si indicas la marca, el producto aparece a los due\xF1os de ese veh\xEDculo. D\xE9jala vac\xEDa para agregarla despu\xE9s.'}),h('div',{class:'grid2'},make,model),h('div',{class:'grid2'},from,to),send);
 f.onsubmit=async e=>{e.preventDefault();const amount=numberOrNull(price.value);const units=numberOrNull(stock.value);const y1=numberOrNull(from.value);const y2=numberOrNull(to.value);
  if(!(amount>0)){status('Escribe un precio mayor que cero.');return;}if(Number.isNaN(units)||(units!==null&&(units<0||!Number.isInteger(units)))){status('El stock debe ser un n\xFAmero entero, desde cero.');return;}
  if(!make.value.trim()&&(model.value.trim()||y1!==null||y2!==null)){status('Para indicar modelo o a\xF1os, escribe tambi\xE9n la marca.');return;}
  if((y1!==null&&Number.isNaN(y1))||(y2!==null&&Number.isNaN(y2))||(y1!==null&&y2!==null&&y1>y2)){status('Revisa los a\xF1os: el inicial no puede ser mayor que el final.');return;}
  send.disabled=true;
  try{const body={name:name.value.trim(),price:amount};if(units!==null)body.stock=units;const product=await api('/products',{method:'POST',body:JSON.stringify(body)});
   let msg='Agregaste '+body.name+'.';
   if(make.value.trim()){try{await api('/pilot/catalog/'+encodeURIComponent(product.id)+'/fitment',{method:'POST',body:JSON.stringify({make:make.value.trim(),model:model.value.trim()||null,yearFrom:y1,yearTo:y2})});}catch(err){msg+=' El producto qued\xF3 sin compatibilidad: '+err.message;}}
   f.reset();status(msg);await done();}
  catch(err){status(err.message);}finally{send.disabled=false;}};
 return f;}
function fitmentText(x){const years=x.yearFrom!==null&&x.yearTo!==null?(x.yearFrom===x.yearTo?String(x.yearFrom):x.yearFrom+' a '+x.yearTo):x.yearFrom!==null?'desde '+x.yearFrom:x.yearTo!==null?'hasta '+x.yearTo:'todos los a\xF1os';return x.make+' '+(x.model||'todos los modelos')+' \xB7 '+years;}
function productRow(it,done){
 const box=h('div',{class:'line'});const run=afterSave(done);
 const info=h('div',{},h('b',{text:it.name}),h('small',{text:usd(it.priceUsd)+(it.stock!==null?' \xB7 '+(it.stock>0?it.stock+' en stock':'sin stock'):'')}),it.active?null:h('span',{class:'tag st-urgente',text:'Desactivado: no lo ven los compradores'}));
 for(const x of it.fitments)info.append(h('div',{class:'acts'},h('small',{text:'Compatible: '+fitmentText(x)}),btn('Quitar compatibilidad','ghost',()=>{if(!window.confirm('\xBFQuitar esta compatibilidad?'))return;void run(async()=>{await api('/pilot/catalog/'+encodeURIComponent(it.id)+'/fitment/'+encodeURIComponent(x.id)+'/remove',{method:'POST',body:'{}'});return 'Quitaste la compatibilidad.';});})));
 if(!it.fitments.length)info.append(h('small',{text:'Sin compatibilidad: no aparece en la tarjeta de repuestos de ning\xFAn due\xF1o.'}));
 const acts=h('div',{class:'acts'});
 acts.append(btn('Editar precio y stock','ghost',()=>editProduct(it,acts,run)),btn('Agregar compatibilidad','ghost',()=>addFitment(it,acts,run)),
  btn(it.active?'Desactivar':'Activar','ghost',()=>{if(it.active&&!window.confirm('\xBFDesactivar '+it.name+'? Dejar\xE1 de mostrarse a los compradores y podr\xE1s activarlo otra vez.'))return;void run(async()=>{await api('/pilot/catalog/'+encodeURIComponent(it.id)+'/active',{method:'POST',body:JSON.stringify({active:!it.active})});return it.active?'Desactivaste '+it.name+'.':'Activaste '+it.name+'.';});}));
 info.append(acts);box.append(info);return box;}
function editProduct(it,acts,run){
 const price=inp('Precio en USD',{type:'number',required:true,min:'0.01',max:'99999999',step:'0.01',inputmode:'decimal',value:String(it.priceUsd)});
 const stock=inp('Stock',{type:'number',min:'0',max:'1000000',step:'1',inputmode:'numeric',value:it.stock===null?'':String(it.stock)});
 const f=h('form',{class:'acts'},price,stock,h('button',{class:'ghost'},'Guardar'));
 f.onsubmit=e=>{e.preventDefault();const amount=numberOrNull(price.value);const units=numberOrNull(stock.value);
  if(!(amount>0)){status('Escribe un precio mayor que cero.');return;}if(Number.isNaN(units)||(units!==null&&(units<0||!Number.isInteger(units)))){status('El stock debe ser un n\xFAmero entero, desde cero.');return;}
  const body={price:amount};if(units!==null)body.stock=units;
  void run(async()=>{await api('/products/'+encodeURIComponent(it.id),{method:'PATCH',body:JSON.stringify(body)});return 'Actualizaste '+it.name+'.';});};
 acts.replaceChildren(f);price.focus();}
function addFitment(it,acts,run){
 const make=inp('Marca',{required:true,maxlength:'60'});const model=inp('Modelo (opcional)',{maxlength:'60'});
 const from=inp('A\xF1o desde',{type:'number',min:'1950',max:'2100',inputmode:'numeric'});const to=inp('A\xF1o hasta',{type:'number',min:'1950',max:'2100',inputmode:'numeric'});
 const f=h('form',{class:'acts'},make,model,from,to,h('button',{class:'ghost'},'Agregar'));
 f.onsubmit=e=>{e.preventDefault();const y1=numberOrNull(from.value);const y2=numberOrNull(to.value);
  if((y1!==null&&Number.isNaN(y1))||(y2!==null&&Number.isNaN(y2))||(y1!==null&&y2!==null&&y1>y2)){status('Revisa los a\xF1os: el inicial no puede ser mayor que el final.');return;}
  void run(async()=>{await api('/pilot/catalog/'+encodeURIComponent(it.id)+'/fitment',{method:'POST',body:JSON.stringify({make:make.value.trim(),model:model.value.trim()||null,yearFrom:y1,yearTo:y2})});return 'Agregaste la compatibilidad.';});};
 acts.replaceChildren(f);make.focus();}
// ---------- Tarifario, horario y domicilio del taller ----------
function tarifarioCard(d){
 const body=h('div',{class:'stack'},h('p',{class:'note',text:'Cargando\u2026'}));
 const c=card('Tarifario, horario y domicilio',null,body);c.id='tarifario';
 const load=async()=>{const epoch=generation;let x;try{x=await api('/pilot/shop-extras');}catch(err){body.replaceChildren(h('p',{class:'note',text:err.message}));return;}
  if(epoch!==generation)return;body.replaceChildren(tariffBlock(x,load),hoursBlock(x,load),pickupBlock(x,load));};
 void load();return c;}
function tariffBlock(x,done){
 const run=afterSave(done);const box=h('div',{class:'stack'},h('p',{class:'sub',text:'Tarifario (precio desde, en USD)'}),h('p',{class:'note',text:TARIFF_NOTE+' No genera un presupuesto.'}));
 if(x.updatePending)box.append(h('p',{class:'note',text:'Para usar el tarifario, el horario por d\xEDa y el domicilio, el equipo debe activar esta funci\xF3n.'}));
 const list=h('div',{class:'list'});
 for(const t of x.tariff){const row=h('div',{class:'line'},h('div',{},h('b',{text:t.name}),h('small',{text:'Desde '+usd(t.priceFromUsd)+(t.durationMin?' \xB7 aprox. '+minText(t.durationMin):'')}),t.active?null:h('span',{class:'tag st-urgente',text:'Desactivado: no se muestra en tu perfil'})));
  if(x.canManage){const acts=h('div',{class:'acts'});acts.append(btn('Editar','ghost',()=>editTariff(t,acts,run)),btn(t.active?'Desactivar':'Activar','ghost',()=>{if(t.active&&!window.confirm('\xBFQuitar '+t.name+' de tu perfil? Podr\xE1s activarlo otra vez.'))return;void run(async()=>{await api('/pilot/tariff/'+encodeURIComponent(t.id)+'/active',{method:'POST',body:JSON.stringify({active:!t.active})});return t.active?'Quitaste '+t.name+' de tu perfil.':'Activaste '+t.name+'.';});}));row.firstChild.append(acts);}
  list.append(row);}
 box.append(x.tariff.length?list:h('p',{class:'note',text:'Todav\xEDa no tienes servicios en el tarifario.'}));
 if(!x.canManage){box.append(h('p',{class:'note',text:'Solo el due\xF1o del taller o un administrador puede cambiar el tarifario.'}));return box;}
 const name=inp('Servicio (por ejemplo, Cambio de aceite)',{required:true,minlength:'3',maxlength:'120'});
 const price=inp('Precio desde en USD',{type:'number',required:true,min:'0.01',max:'100000',step:'0.01',inputmode:'decimal'});
 const mins=inp('Duraci\xF3n aproximada en minutos (opcional)',{type:'number',min:'5',max:'1440',step:'1',inputmode:'numeric'});
 const f=h('form',{class:'stack'},name,h('div',{class:'grid2'},price,mins),h('button',{class:'primary full'},'Agregar servicio'));
 f.onsubmit=e=>{e.preventDefault();const body=tariffBody(name,price,mins);if(!body)return;void run(async()=>{await api('/pilot/tariff',{method:'POST',body:JSON.stringify(body)});return 'Agregaste '+body.name+' a tu tarifario.';});};
 box.append(f);return box;}
function tariffBody(name,price,mins){const amount=numberOrNull(price.value);const m=numberOrNull(mins.value);
 if(!(amount>0)){status('Escribe un precio desde mayor que cero.');return null;}if(Number.isNaN(m)||(m!==null&&(!Number.isInteger(m)||m<5||m>1440))){status('La duraci\xF3n debe ser un n\xFAmero entero de minutos, entre 5 y 1440.');return null;}
 return {name:name.value.trim(),priceFromUsd:amount,durationMin:m};}
function editTariff(t,acts,run){
 const name=inp('Servicio',{required:true,minlength:'3',maxlength:'120',value:t.name});
 const price=inp('Precio desde en USD',{type:'number',required:true,min:'0.01',max:'100000',step:'0.01',inputmode:'decimal',value:String(t.priceFromUsd)});
 const mins=inp('Duraci\xF3n en minutos (opcional)',{type:'number',min:'5',max:'1440',step:'1',inputmode:'numeric',value:t.durationMin?String(t.durationMin):''});
 const f=h('form',{class:'acts'},name,price,mins,h('button',{class:'ghost'},'Guardar'));
 f.onsubmit=e=>{e.preventDefault();const body=tariffBody(name,price,mins);if(!body)return;void run(async()=>{await api('/pilot/tariff/'+encodeURIComponent(t.id),{method:'POST',body:JSON.stringify(body)});return 'Actualizaste '+body.name+'.';});};
 acts.replaceChildren(f);name.focus();}
function hoursBlock(x,done){
 const run=afterSave(done);const box=h('div',{class:'stack'},h('p',{class:'sub',text:'Horario por d\xEDa'}));
 const week=x.weeklyHours||{};
 if(!x.canManage){const list=h('div',{class:'list'});for(const [k,label] of DAY_LIST)list.append(h('div',{class:'line'},h('span',{text:label}),h('span',{class:'mono',text:week[k]?week[k].from+' a '+week[k].to:'Cerrado'})));box.append(x.weeklyHours?list:h('p',{class:'note',text:'Todav\xEDa no hay horario por d\xEDa.'}));return box;}
 box.append(h('p',{class:'note',text:'Se muestra en tu perfil y las citas directas solo se aceptan dentro de \xE9l. Cada cita dura una hora. Si no defines horario por d\xEDa, se usa el horario general de la agenda.'}));
 const rows=DAY_LIST.map(([k,label])=>{const open=h('input',{type:'checkbox','aria-label':label+': abierto'});open.checked=Boolean(week[k]);Object.assign(open.style,{flex:'none',minHeight:'0',width:'auto'});
  const from=h('input',{type:'time',required:true,'aria-label':label+': abre',value:week[k]?week[k].from:'08:00'});const to=h('input',{type:'time',required:true,'aria-label':label+': cierra',value:week[k]?week[k].to:'18:00'});
  const sync=()=>{from.disabled=to.disabled=!open.checked;};open.onchange=sync;sync();
  from.style.flex=to.style.flex='1 1 90px';
  return {k,open,from,to,row:h('div',{class:'acts'},h('label',{class:'consent'},open,label),from,to)};});
 const f=h('form',{class:'stack'},...rows.map(r=>r.row),h('button',{class:'primary full'},'Guardar horario'));
 f.onsubmit=e=>{e.preventDefault();const days={};for(const r of rows){if(!r.open.checked)continue;if(!r.from.value||!r.to.value||r.to.value<r.from.value||(Number(r.to.value.slice(0,2))*60+Number(r.to.value.slice(3,5)))-(Number(r.from.value.slice(0,2))*60+Number(r.from.value.slice(3,5)))<60){status('En cada d\xEDa abierto, el cierre debe ser al menos una hora despu\xE9s de la apertura.');return;}days[r.k]={from:r.from.value,to:r.to.value};}
  if(!Object.keys(days).length){status('Marca al menos un d\xEDa abierto, o usa \xABQuitar horario por d\xEDa\xBB.');return;}
  void run(async()=>{await api('/pilot/shop-hours',{method:'POST',body:JSON.stringify({days})});return 'Guardaste tu horario por d\xEDa.';});};
 box.append(f);
 if(x.weeklyHours)box.append(btn('Quitar horario por d\xEDa','ghost',()=>{if(!window.confirm('\xBFQuitar el horario por d\xEDa? Las citas directas volver\xE1n a usar el horario general de la agenda.'))return;void run(async()=>{await api('/pilot/shop-hours',{method:'POST',body:JSON.stringify({days:null})});return 'Quitaste el horario por d\xEDa.';});}));
 return box;}
function pickupBlock(x,done){
 const run=afterSave(done);const box=h('div',{class:'stack'},h('p',{class:'sub',text:'Retiro y entrega a domicilio'}),h('p',{class:'note',text:x.offersPickup?'Ofreces retiro y entrega a domicilio. El due\xF1o puede pedirlo al solicitar su cita, con su sector o una referencia. No se cobra ni se da seguimiento autom\xE1tico: lo acuerdan ustedes.':'No ofreces retiro y entrega a domicilio.'}));
 if(x.canManage)box.append(btn(x.offersPickup?'Dejar de ofrecer domicilio':'Ofrecer retiro y entrega a domicilio','ghost',()=>{if(!window.confirm(x.offersPickup?'\xBFDejar de ofrecer retiro y entrega a domicilio?':'\xBFOfrecer retiro y entrega a domicilio? Los due\xF1os podr\xE1n pedirlo al solicitar su cita.'))return;void run(async()=>{await api('/pilot/shop-pickup',{method:'POST',body:JSON.stringify({offers:!x.offersPickup})});return x.offersPickup?'Dejaste de ofrecer domicilio.':'Ahora ofreces retiro y entrega a domicilio.';});}));
 return box;}
// ---------- Perfil del taller que ve el due\xF1o, y su cita directa ----------
function profileExtras(out,p){
 const box=h('div',{class:'stack'});
 if(p.weeklyHours){const list=h('div',{class:'list'});for(const r of p.weeklyHours)list.append(h('div',{class:'line'},h('span',{text:r.label}),h('span',{class:'mono',text:r.text})));box.append(h('p',{class:'sub',text:'Horario por d\xEDa'}),list);}
 if(p.tariff&&p.tariff.length){const list=h('div',{class:'list'});for(const t of p.tariff)list.append(h('div',{class:'line'},h('div',{},h('b',{text:t.name}),t.durationMin?h('small',{text:'Duraci\xF3n aproximada: '+minText(t.durationMin)}):null),h('span',{class:'price',text:'Desde '+usd(t.priceFromUsd)})));box.append(h('p',{class:'sub',text:'Servicios y precios desde'}),list,h('p',{class:'note',text:p.tariffNote||TARIFF_NOTE}));}
 if(p.offersPickup)box.append(h('span',{class:'tag st-al_dia',text:'Ofrece retiro y entrega a domicilio'}));
 const first=out.children[1];if(first&&box.children.length)first.after(box);}
const pickupFields=new WeakMap();
function pickupControls(p,f,send){
 if(!p.offersPickup)return;
 const on=h('input',{type:'checkbox','aria-label':'Quiero retiro y entrega a domicilio'});
 const note=h('input',{maxlength:'120',minlength:'3','aria-label':'Sector o referencia del retiro',placeholder:'Sector o referencia (sin tel\xE9fonos)'});note.hidden=true;
 on.onchange=()=>{note.hidden=!on.checked;note.required=on.checked;if(on.checked)note.focus();};
 pickupFields.set(f,{on,note});
 send.before(h('label',{class:'consent'},on,'Quiero retiro y entrega a domicilio'),note,h('p',{class:'note',text:'El taller recibe tu sector o referencia. No tiene costo autom\xE1tico ni seguimiento: lo acuerdas con el taller.'}));}
function pickupBody(f){const x=pickupFields.get(f);return x&&x.on.checked&&x.note.value.trim()?{pickupNote:x.note.value.trim()}:{};}
`;

