function slugify(text12) {
  return text12.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
var money3 = (value2) => `US$ ${value2.toFixed(0)}`;
function buildServicePages() {
  return serviceTaxonomy.categories.map((category) => {
    const items = category.subservices.filter((sub) => !sub.name.toLowerCase().includes("moto") && !sub.detail?.toLowerCase().includes("motocicleta")).map((sub) => ({
      name: sub.name,
      detail: sub.detail ?? "",
      durationMin: typeof sub.durationMin === "number" ? sub.durationMin : null,
      costRefUsd: typeof sub.costRefUsd === "number" ? sub.costRefUsd : null,
      costNote: sub.costNote ?? null
    }));
    const precios = items.map((i) => i.costRefUsd).filter((v) => typeof v === "number");
    const priceFrom = precios.length ? Math.min(...precios) : null;
    const priceTo = precios.length ? Math.max(...precios) : null;
    const rango = priceFrom === null ? "" : priceFrom === priceTo ? ` Precio referencial: ${money3(priceFrom)}.` : ` Precios referenciales desde ${money3(priceFrom)} hasta ${money3(priceTo)}.`;
    return {
      slug: slugify(category.name),
      id: category.id,
      name: category.name,
      title: `${category.name} para tu veh\xEDculo en Ecuador \xB7 precios y talleres`,
      description: `${category.name}: qu\xE9 incluye, cu\xE1nto demora y cu\xE1nto cuesta en Ecuador.${rango} Agenda en un taller revisado por WhatsApp, sin instalar nada.`,
      items,
      priceFrom,
      priceTo
    };
  });
}
